<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Bouncing Ball Physics Playground</title>
    <style>
        :root {
            --bg-color: #1a1a1d;
            --text-color: #c5c6c7;
            --accent-color: #4caf50;
            --btn-bg: #323338;
            --btn-hover: #3e3f46;
        }

        body {
            margin: 0;
            height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        #app {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 20px;
        }

        h1 {
            font-weight: 300;
            margin-bottom: 10px;
            font-size: 1.5rem;
        }

        #sim-container {
            position: relative;
            padding: 4px;
            border-radius: 8px;
            box-shadow: 0 0 20px rgba(0,0,0,0.5);
        }

        #sim {
            background-color: #000;
            display: block;
            border-radius: 6px;
            cursor: crosshair;
            touch-action: none; /* Prevent scrolling on touch */
        }

        .controls {
            display: flex;
            gap: 10px;
            margin-top: 15px;
        }

        button {
            padding: 8px 16px;
            border: none;
            border-radius: 4px;
            background-color: var(--btn-bg);
            color: #fff;
            font-size: 1rem;
            cursor: pointer;
            transition: background-color 0.2s, transform 0.1s;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            font-weight: 600;
        }

        button:hover {
            background-color: var(--btn-hover);
        }

        button:active {
            transform: scale(0.98);
        }

        #play.pressed {
            background-color: var(--accent-color);
            color: #000;
        }
    </style>
</head>
<body>

<div id="app">
    <div id="sim-container">
        <canvas id="sim" width="600" height="450"></canvas>
    </div>

    <div class="controls">
        <button id="drop">Drop Ball</button>
        <button id="play">Play / Pause</button>
        <button id="clear">Clear All</button>
    </div>
</div>

<script>
(function() {
    // --- Configuration & Constants ---
    const GRAVITY = 0.4;       // Downward acceleration per step
    const FRICTION_X = 1.0;    // No air resistance on walls (bouncy)
    const RESTITUTION = 0.85;  // Energy loss on bounce (< 1 = energy loss)

    // --- State ---
    const canvas = document.getElementById('sim');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    // Store balls in a flat array. We will attach this to the API object for easy access
    let ballsArray = [];

    // Animation state
    let isPlaying = true;
    let animationFrameId = null;

    // --- Helper Functions ---

    function random(min, max) {
        return Math.random() * (max - min) + min;
    }

    function randomColor() {
        const hue = Math.floor(Math.random() * 360);
        return `hsl(${hue}, 80%, 60%)`;
    }

    // --- Physics Engine (step) ---

    function step(dt = 1) {
        // Update physics for all balls
        ballsArray.forEach(ball => {
            // Apply Gravity
            ball.vy += GRAVITY;

            // Update Position
            ball.x += ball.vx * dt;
            ball.y += ball.vy * dt;

            // --- Collision Detection & Response (Walls) ---

            // Floor (Bottom)
            if (ball.y + ball.r > height) {
                ball.y = height - ball.r; // Clamp position
                ball.vy *= -RESTITUTION;  // Reverse velocity with loss
            } 
            // Ceiling (Top)
            else if (ball.y - ball.r < 0) {
                ball.y = ball.r;
                ball.vy *= -RESTITUTION;
            }

            // Right Wall
            if (ball.x + ball.r > width) {
                ball.x = width - ball.r;
                ball.vx *= -RESTITUTION;
            } 
            // Left Wall
            else if (ball.x - ball.r < 0) {
                ball.x = ball.r;
                ball.vx *= -RESTITUTION;
            }

            // Visual polish: slightly increase mass or radius over time? No, keep constant.
        });

        draw();

        if (isPlaying) {
            animationFrameId = requestAnimationFrame(() => step());
        }
    }

    function draw() {
        // Clear canvas
        ctx.fillStyle = '#111'; // Dark background for the canvas content
        ctx.clearRect(0, 0, width, height);

        // Draw a subtle grid or border
        ctx.strokeStyle = '#333';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, width, height);

        // Draw balls
        if (ballsArray.length === 0) return;

        ballsArray.forEach(ball => {
            ctx.beginPath();
            ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);

            // Color gradient or solid? Solid is cleaner.
            ctx.fillStyle = '#333'; 

            // Add border to see shape clearly
            ctx.strokeStyle = randomColor(); 
            ctx.lineWidth = 1;

            // Draw main fill darker
            ctx.fill();
            ctx.stroke();

            // Simple shadow logic: draw a dark ellipse below the ball if on screen
            // (Optional, adds depth)
        });
    }

    // --- Public API for Grading System ---

    window.sim = {
        w: width,
        h: height,

        /**
         * Returns the current list of balls.
         */
        balls() {
            return ballsArray;
        },

        /**
         * Adds a new ball to the simulation.
         * @param {number} x - X position (0 to width)
         * @param {number} y - Y position (0 to height)
         * @param {number} vx - Initial velocity X
         * @param {number} vy - Initial velocity Y
         * @param {number} r - Radius
         */
        addBall(x, y, vx = 0, vy = 0, r = 20) {
            const ball = {
                x: x,
                y: y,
                vx: vx,
                vy: vy,
                r: Math.max(5, Math.min(r || random(10, 40), width/3)), // Clamp size to prevent clipping logic errors easily
                color: randomColor()
            };
            ballsArray.push(ball);

            // If we are paused, draw immediately to see the added ball
            if (!isPlaying) {
                draw(); 
            } else {
                 // Trigger a step so physics handles immediate collisions if dropping from top
                 step(1);
            }
        },

        /**
         * Removes all balls.
         */
        clear() {
            ballsArray = [];
            draw();
        },

        /**
         * Advances the simulation by one time step (dt) and redraws.
         * If playing, this triggers the loop. If paused, it just updates once.
         */
        step(dt = 1) {
            if(isPlaying) {
                // In a real app, we usually separate logic vs rendering in loops.
                // Here, we assume step() is called inside the requestAnimationFrame loop internally.
            }

            // Logic: Update physics and redraw regardless of play state 
            // so that API users can step manually or if toggled off.
            ballsArray.forEach(ball => {
                ball.vy += GRAVITY;
                ball.x += ball.vx * dt;
                ball.y += ball.vy * dt;

                // Wall collisions (Bottom)
                if (ball.y + ball.r > height) {
                    ball.y = height - ball.r;
                    ball.vy *= -RESTITUTION;
                }
                // Ceiling
                else if (ball.y - ball.r < 0) {
                    ball.y = ball.r;
                    ball.vy *= -RESTITUTION;
                }

                // Wall collisions (Right)
                if (ball.x + ball.r > width) {
                    ball.x = width - ball.r;
                    ball.vx *= -RESTITUTION;
                }
                // Wall collisions (Left)
                else if (ball.x - ball.r < 0) {
                    ball.x = ball.r;
                    ball.vx *= -RESTITUTION;
                }
            });

            draw();
        },

        /**
         * Set or get the paused state.
         */
        isPlaying: false,

        togglePlay() {
            // Used for button logic below
            isPlaying = !isPlaying;

            if (isPlaying) {
                step(); // Start loop
                // We use a loop that calls requestAnimationFrame
                // But to avoid double stepping immediately inside the loop, we handle it differently:
                // Actually, simple recursion inside RAF works best here for simplicity.
            } else {
                cancelAnimationFrame(animationFrameId);
            }

            // UI button state
            const btn = document.getElementById('play');
            if(isPlaying) btn.classList.add('pressed');
            else btn.classList.remove('pressed');
        },

        draw: () => draw() // Expose draw for debugging if needed
    };

    // --- UI Event Listeners ---

    // Setup Play Button
    const playBtn = document.getElementById('play');

    // We need a slightly more robust loop than just step inside step.
    let animationId;

    function animateLoop() {
        step(); // Update physics and draw
        if (isPlaying) {
            animationId = requestAnimationFrame(animateLoop);
        }
    }

    playBtn.addEventListener('click', () => {
        window.sim.togglePlay();

        // Re-attach the recursive call logic
        if (isPlaying) {
            animateLoop();
        } else {
            cancelAnimationFrame(animationId);
        }
    });

    // Setup Clear Button
    document.getElementById('clear').addEventListener('click', () => {
        window.sim.clear();
        // Reset play state just to keep it clean (or keep paused)
        if(isPlaying) step(); // Draw one last time for empty state

        const btn = document.getElementById('play');
        btn.classList.remove('pressed');
    });

    // Setup Drop Button
    document.getElementById('drop').addEventListener('click', () => {
        // Add a ball at random X position, slightly above center Y
        window.sim.addBall(
            random(width * 0.2, width * 0.8), 
            height * 0.1, // Start high up
            random(-5, 5), // Some horizontal randomness
            random(-15, -5), // Throw slightly down
            random(15, 30)  // Random size
        );
    });

    // Setup Canvas Click (Add Ball at Cursor)
    canvas.addEventListener('mousedown', (e) => {
        const rect = canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        // Add ball with a little random horizontal kick and drop downwards
        window.sim.addBall(x, y, random(-5, 5), random(-10, -2));
    });

    // Initial Setup
    window.sim.clear();

})();
</script>
</body>
</html>
